INSERT INTO public.generator_pools (id, generator_type, system_code, payload_json, created_at, updated_at, subtype) VALUES (17, 'twist', 'any', '{"entries": [{"scene": "Walka", "result": "Do starcia dołącza trzecia strona z własnym celem.", "intensity": "Średni"}, {"scene": "Negocjacje", "result": "Rozmówca rozpoznaje jednego z bohaterów z przeszłości.", "intensity": "Lekki"}, {"scene": "Śledztwo", "result": "Najbardziej oczywisty świadek sam sfabrykował część dowodów.", "intensity": "Ciężki"}, {"scene": "Podróż", "result": "Trasa jest celowo oznaczona fałszywymi znakami.", "intensity": "Średni"}]}', '2026-05-14 10:03:18.073207+00', '2026-05-14 10:03:18.073207+00', 'default');
INSERT INTO public.generator_pools (id, generator_type, system_code, payload_json, created_at, updated_at, subtype) VALUES (18, 'hook', 'any', '{"entries": [{"lead": "Studnia, dawny grabarz i księga gości.", "mood": "Tajemnica", "scale": "Lokalna", "detail": "Ktoś każdej nocy zostawia mokre ślady prowadzące do zamkniętej studni.", "situation": "Karczmarz prosi drużynę o dyskrecję."}, {"lead": "Mapa trasy, ocalały muł i dziwny srebrny pył.", "mood": "Przygodowy", "scale": "Regionalna", "detail": "Poprzednia eskorta wróciła bez pamięci ostatnich dwóch dni.", "situation": "Kupiecka karawana szuka eskorty."}, {"lead": "Wieża, zakrystia i stary cmentarz.", "mood": "Horror", "scale": "Lokalna", "detail": "Od trzech dni nikt nie widział kapłana.", "situation": "Dzwon świątynny bije sam o świcie."}]}', '2026-05-14 10:03:18.073207+00', '2026-05-14 10:03:18.073207+00', 'default');
INSERT INTO public.generator_pools (id, generator_type, system_code, payload_json, created_at, updated_at, subtype) VALUES (19, 'complication', 'any', '{"entries": ["Ktoś nieoczekiwanie dołącza do sceny i zna niewygodny sekret.", "Pogoda gwałtownie się załamuje, utrudniając widoczność i ruch.", "Wiadomość wymaga natychmiastowej decyzji, zanim scena się skończy.", "Niewinny świadek widzi coś, czego nie powinien widzieć."]}', '2026-05-14 10:03:18.073207+00', '2026-05-14 10:03:18.073207+00', 'default');
