INSERT INTO public.generator_pools (id, generator_type, system_code, payload_json, created_at, updated_at, subtype) VALUES (28, 'trap', 'any', '{"names": ["Szept Ostrzy", "Schody Głodnego Kamienia", "Pieczęć Zimnego Oddechu", "Studnia Fałszywego Echa", "Zegar Czarnego Piasku"], "types": ["Mechaniczna", "Magiczna", "Środowiskowa", "Puzzle"], "disarms": ["zablokować przeciwwagę cienkim klinem", "odtworzyć brakujący fragment symbolu", "przytrzymać dźwignię przez trzy oddechy", "wyjąć fałszywy pin i obrócić pierścień mechanizmu", "odwrócić uwagę zaklęcia krótkim źródłem światła"], "effects": ["ostrza wysuwają się z dwóch stron korytarza", "z sufitu opada zimna mgła usypiająca czujność", "podłoga przechyla się w stronę ukrytego szybu", "magiczny impuls przyciąga metalowe przedmioty do ściany", "pomieszczeńie zamyka się i zaczyna powoli wypełniać wodą"], "triggers": ["naciśnięcie trzeciej płyty od wejścia", "otwarcie skrzyni bez wypowiedzenia hasła", "przerwanie linii kredowego symbolu", "zabranie przedmiotu z cokołu", "rzucenie cienia na srebrny znak"], "detections": ["delikatne rysy na podłodze układają się w wachlarz", "w powietrzu czuć metaliczny zapach", "kurz nie osiada na jednej części posadzki", "jedna ściana odbija dźwięk z opóźnieniem", "na krawędzi mechanizmu widać świeży tłuszcz"], "consequences": ["hałas alarmuje pobliskich strażników", "pułapka niszczy część łupu", "ofiara zostaje rozdzielona od reszty grupy", "na bohaterach zostaje widoczny magiczny znak", "droga powrotna staje się trudniejsza"]}', '2026-05-14 10:03:18.236511+00', '2026-05-14 10:03:18.236511+00', 'general.quick');
