": "solo", "environments": ["Bagna", "Gory"]}, {"cr": "6", "xp": 2300, "name": "Maga renegata", "role": "caster", "environments": ["Miasto", "Ruiny", "Lochy"]}], "solutions": ["perswazja i ujawnienie dowodu", "skradanie oraz odciecie zrodla problemu", "przekupstwo albo wymiana przyslug", "pokaz sily bez rozlewu krwi", "test grupowy z jasna konsekwencja porazki"], "objectives": ["przetrwac trzy rundy, zanim nadejdzie wsparcie", "przerwac rytual przed koncem sceny", "ochronic swiadka albo przewodnika", "odzyskac przedmiot i uciec bez dalszej walki", "przejac kontrolny punkt lokacji"], "skillChallenges": ["3 sukcesy przed 2 porazkami: Perswazja, Wglad, Historia", "4 sukcesy przed 3 porazkami: Skradanie, Percepcja, Zlodziejskie narzędzia", "3 sukcesy przed 2 porazkami: Atletyka, Akrobatyka, Survival", "4 sukcesy przed 2 porazkami: Religia, Arkana, Perswazja"], "nonCombatConflicts": ["lokalni straznicy oskarzaja niewlasciwa osobę", "dwie frakcje probuja kupic milczenie tego samego swiadka", "przestraszony informator odmawia rozmowy bez gwarancji bezpieczenstwa", "rytual może zostac przerwany tylko przez negocjacje z uczestnikami", "tlum blokuje droge, bo wierzy w fałszywa plotke"], "environmentFeatures": {"Las": ["gesta mgla ograniczajaca widocznosc", "powalone drzewo tworzace naturalna barykade", "gniazdo os na skraju polany"], "Gory": ["osuwisko kamieni przy glosnych dzwiekach", "waske przejscie nad przepascia", "silny wiatr utrudniajacy strzaly"], "Bagna": ["grzaski teren spowalniajacy ruch", "trujace opary w niskich zaglebieniach", "ukryta woda po pas"], "Lochy": ["waski most nad czarna studnia", "ruchome kraty dzielace pole walki", "wilgotne schody dajace przewage obroncom"], "Ruiny": ["niestabilna kolumna gotowa runac", "zapadnieta posadzka ukrywajaca piwnice", "stary magiczny krag wzmacniajacy zaklecia"], "Miasto": ["tlum cywilow blokujacy linie strzalu", "wozy i stragany jako oslony", "alarmujacy dzwon straży miejskiej"], "Podziemia": ["krysztaly odbijajace światlo", "tunel o niskim sklepieniu", "cieply wyziew z pekniecia w skale"]}, "failureConsequences": ["cel ucieka i zostawia fałszywy trop", "relacje z lokalna frakcja pogarszaja sie", "drużyna traci czas i przeciwnicy wzmacniaja pozycje", "niewinny NPC ponosi koszt decyzji bohaterow", "powstaje publiczna plotka uderzajaca w reputacje drużyny"]}', '2026-05-14 10:03:18.275208+00', '2026-05-14 10:03:18.275208+00', 'dnd.quick');
INSERT INTO public.generator_pools (id, generator_type, system_code, payload_json, created_at, updated_at, subtype) VALUES (26, 'npc', 'any', '{"hooks": ["prosi o rozmowe po zmroku", "rozpoznaje przedmiot drużyny", "zna skrot do waznego miejsca", "potrzebuje ochrony na jedna noc", "ma list, którego nie powinien miec", "oferuje prace bez zadawania pytan", "znika zaraz po spotkaniu", "wskazuje fałszywy trop z dobrego powodu", "chce wymienic sekret za przysluge", "jest obserwowany przez kogos z tlumu", "przypadkiem zdradza wazna date", "płaci stara moneta", "zostawia znak na stole", "ma mape bez legendy", "szuka kogos podobnego do jednego z bohaterow", "prosi o odzyskanie paczki", "twierdzi, ze zna przyszly problem", "ma ranę, której nie chce wyjasnic", "wzywa druzynę do miejsca publicznego", "zostawia ostrzezenie zamiast nagrody"], "roles": ["Straznik", "Kupiec", "Kaplan", "Najemnik", "Skryba", "Zwiadowca", "Medyk", "Bibliotekarz", "Mechanik", "Przemytnik", "Dyplomata", "Kartograf", "Archiwista", "Patolog", "Reporter", "Medium", "Celnik", "Herold", "Lowca relikwii", "Radiooperator"], "secrets": ["zna prawdziwego winnego", "pracuje dla rywala", "ma fałszywe nazwisko", "ukryl dowod w bezpiecznym miejscu", "wie o drugim wejsciu", "zdradzil kogos bliskiego", "jest szantazowany", "chroni osobę poszukiwana", "ma dlog wobec frakcji", "widzial cos niemozliwego", "sprzedal informacje dwa razy", "boi sie jednego symbolu", "zna haslo do zamknietej czesci miasta", "jest ostatnim swiadkiem sprawy", "udaje nizszy status", "ukrywa chorobe", "dostal rozkaz milczenia", "ma przy sobie cudzy list", "zna lokalna trase ucieczki", "nie jest tym, za kogo sie podaje"], "givenNames": ["Alaric", "Mira", "Thorin", "Selene", "Varis", "Eldrin", "Kaela", "Brom", "Isolde", "Darian", "Runa", "Tavian", "Liora", "Kest", "Nadia", "Oren", "Sana", "Marek", "Irena", "Tomasz"], "appearances": ["znoszony plaszcz i czujne spojrzenie", "drogi dodatek przy prostym stroju", "rece przyzwyczajone do pracy", "bliz