INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (1, 'Mistrz Gry', 'Game Master / Dungeon Master', 'Osoba prowadząca grę — organizuje rozgrywkę, opisuje świat oraz kontroluje postacie niezależne (NPC) i wydarzenia.', 'podstawy', 'uniwersalne', 'gm,dm,podstawy', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (2, 'Postać Gracza', 'Player Character', 'Postać w grze kontrolowana przez gracza, a nie przez Mistrza Gry.', 'postacie', 'uniwersalne', 'pc,postacie', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (3, 'Postać Niezależna', 'Non-Player Character', 'Postacie kontrolowane przez Mistrza Gry. Zaludniają świat i wchodzą w interakcje z postaciami graczy.', 'postacie', 'uniwersalne', 'npc,postacie', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (4, 'Kampania', 'Campaign', 'Seria sesji gry połączonych wspólną fabułą lub zestawem powiązanych przygód.', 'narracja', 'uniwersalne', 'kampania,fabula', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (5, 'Sesja', 'Session', 'Jedno spotkanie, podczas którego rozgrywana jest gra; zwykle trwa kilka godzin.', 'narracja', 'uniwersalne', 'sesja', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (6, 'Przygoda', 'Adventure', 'Konkretne zadanie, misja lub wątek fabularny w ramach kampanii.', 'narracja', 'uniwersalne', 'quest,przygoda', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (7, 'Rzut', 'Dice Roll', 'Czynność polegająca na rzuceniu kośćmi w celu określenia wyniku działania. Typ kości oznacza się literą „d” i liczbą ścian (np. d20).', 'mechanika', 'uniwersalne', 'kosci,mechanika', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (8, 'Punkty Życia', 'Hit Points', 'Miara zdrowia postaci. Gdy HP spadnie do zera, postać zazwyczaj jest nieprzytomna lub martwa.', 'mechanika', 'uniwersalne', 'hp,zycie', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (9, 'Atrybuty', 'Ability Scores', 'Wartości liczbowe opisujące podstawowe cechy postaci, takie jak siła, zręczność czy inteligencja.', 'mechanika', 'uniwersalne', 'atrybuty,statystyki', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (10, 'Inicjatywa', 'Initiative', 'Określa kolejność, w jakiej postacie działają podczas walki lub innych dynamicznych wydarzeń.', 'walka', 'uniwersalne', 'inicjatywa,walka', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (11, 'Walka', 'Combat', 'Ustrukturyzowana sekwencja tur, w której postacie biorą udział w starciu.', 'walka', 'uniwersalne', 'combat,walka', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (12, 'Trafienie Krytyczne / Krytyczna Porażka', 'Critical Hit / Critical Fail', 'Wyjątkowo dobry lub zły wynik rzutu kością, zwykle naturalne 20 lub 1 na k20.', 'walka', 'uniwersalne', 'krytyk,kosci', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (13, 'Odgrywanie ról', 'Roleplaying', 'Odgrywanie działań, decyzji i dialogów postaci poprzez narrację i interakcję.', 'narracja', 'uniwersalne', 'rp,narracja', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (14, 'Lore', 'Lore', 'Historia świata gry, tło fabularne oraz szczegóły worldbuildingu.', 'narracja', 'uniwersalne', 'lore,worldbuilding', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (15, 'Metagranie', 'Metagaming', 'Wykorzystywanie przez gracza wiedzy spoza gry, do której postać nie ma dostępu.', 'meta', 'uniwersalne', 'meta,metagranie', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (16, 'Zasady Domowe', 'House Rules', 'Dodatkowe lub zmodyfikowane zasady wprowadzone przez Mistrza Gry lub grupę.', 'meta', 'uniwersalne', 'houserules', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (17, 'RPG', 'Role-Playing Game', 'Gra fabularna — pojęcie nadrzędne obejmujące zarówno gry stołowe, jak i gry wideo.', 'podstawy', 'uniwersalne', 'rpg', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (18, 'TTRPG / TRPG', 'Tabletop Role-Playing Game', 'Stołowa gra fabularna, używana do odróżnienia jej od komputerowych RPG.', 'podstawy', 'uniwersalne', 'ttrpg,trpg', '2026-05-14 12:03:17.441684');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (19, 'One-shot', 'One-shot', 'Samodzielna, zwykle krótka przygoda zamknięta w jednej sesji albo dwóch spotkaniach.', 'narracja', 'uniwersalne', 'oneshot,przygoda', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (20, 'Session Zero', 'Session Zero', 'Spotkanie organizacyjne przed kampanią, podczas którego ustala się klimat gry, granice i zasady współpracy.', 'meta', 'uniwersalne', 'sessionzero,ustalenia', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (35, 'Ekwipunek podróżny', 'Adventuring Gear', 'Podstawowe przedmioty używane między walkami: liny, racje, pochodnie, narzędzia i zapasy.', 'mechanika', 'uniwersalne', 'ekwipunek,podroz', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (36, 'Tło postaci', 'Character Background', 'Pakiet historii i motywacji postaci, który podpowiada jak odgrywać jej decyzje.', 'postacie', 'uniwersalne', 'background,postac', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (21, 'Railroading', 'Railroading', 'Prowadzenie fabuły tak, aby gracze mieli bardzo mało realnych decyzji i musieli iść jednym torem.', 'meta', 'uniwersalne', 'railroading,fabula', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (22, 'Sandbox', 'Sandbox', 'Styl gry, w którym świat reaguje na decyzje graczy, a fabuła rozwija się głównie przez ich wybory.', 'narracja', 'uniwersalne', 'sandbox,otwarty-swiat', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (23, 'Hook fabularny', 'Story Hook', 'Element fabuły, który ma zainteresować drużynę i popchnąć akcję do przodu.', 'narracja', 'uniwersalne', 'hook,fabula', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (24, 'Test przeciwstawny', 'Opposed Test', 'Sytuacja, w której dwie strony rzucają, a lepszy wynik lub większy poziom sukcesu wygrywa.', 'mechanika', 'uniwersalne', 'test,przeciwstawny', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (25, 'Advantage / Disadvantage', 'Advantage / Disadvantage', 'Modyfikacja rzutu polegająca na rzuceniu dwa razy i wybraniu lepszego albo gorszego wyniku, zależnie od sytuacji.', 'mechanika', 'uniwersalne', 'advantage,disadvantage', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (26, 'Save', 'Saving Throw', 'Rzut obronny wykonywany, by uniknąć lub ograniczyć negatywny efekt, np. zaklęcia albo pułapki.', 'mechanika', 'uniwersalne', 'save,obrona', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (27, 'Condition', 'Status Condition', 'Stan postaci, który czasowo zmienia jej możliwości, np. osłupienie, zatrucie albo przewrócenie.', 'walka', 'uniwersalne', 'status,condition', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (28, 'Crowd Control', 'Crowd Control', 'Zdolności, które ograniczają ruch lub akcje przeciwników zamiast zadawać czyste obrażenia.', 'walka', 'uniwersalne', 'cc,walka', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (29, 'Tempo sceny', 'Scene Pacing', 'Rytm prowadzenia sceny: kiedy przyspieszyć wydarzenia, a kiedy dać miejsce na roleplay i decyzje.', 'narracja', 'uniwersalne', 'tempo,pacing', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (30, 'Retcon', 'Retcon', 'Świadoma korekta wcześniejszego elementu fabuły, aby utrzymać spójność albo naprawić błąd.', 'meta', 'uniwersalne', 'retcon,ciaglosc', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (31, 'Fail Forward', 'Fail Forward', 'Podejście, w którym porażka rzutu nie zatrzymuje historii, tylko wprowadza koszt albo komplikacje.', 'meta', 'uniwersalne', 'fail-forward,komplikacje', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (32, 'Front', 'Adventure Front', 'Pakiet zagrożeń i wydarzeń, które rozwijają się w tle, jeśli drużyna ich nie zatrzyma.', 'narracja', 'uniwersalne', 'front,zagrozenia', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (39, 'Klasa Pancerza', 'Armor Class', 'Wartość liczbowa określająca, jak trudno trafić postać. W D&D 5e bazowa KP wynosi 10 + modyfikator Zręczności. Każda próba ataku musi osiągnąć lub przekroczyć KP celu, aby zadać obrażenia.', 'mechanika', 'dnd', 'KP,AC,obrona,pancerz', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (40, 'Akcja Bonusowa', 'Bonus Action', 'Dodatkowa, szybka akcja wykonywana w tej samej turze co główna akcja. Dostęp do akcji bonusowej dają konkretne zdolności, czary lub cechy klasy — sama w sobie nie daje żadnej czynności.', 'walka', 'dnd', 'akcja,tura,mechanika', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (41, 'Reakcja', 'Reaction', 'Akcja wykonywana w odpowiedzi na konkretny wyzwalacz — np. atak okazji (gdy wróg opuszcza zasięg) lub czar Tarcza. Postać może wykonać tylko jedną reakcję między swoimi turami.', 'walka', 'dnd', 'akcja,tura,mechanika', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (42, 'Koncentracja', 'Concentration', 'Mechanizm utrzymywania aktywnych czarów wymagających skupienia. Postać może koncentrować się tylko na jednym czarze naraz. Otrzymanie obrażeń wymaga testu Kondycji (trudność 10 lub połowa obrażeń) — porażka kończy koncentrację.', 'magia', 'dnd', 'czary,koncentracja,mechanika', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (43, 'Sloty Czarów', 'Spell Slots', 'Zasoby wydawane przy rzucaniu czarów o wyższej niż magiczna sztuczka sile. Każdy slot ma poziom (1–9) — im wyższy, tym potężniejszy czar można nim rzucić. Odnawiane po długim odpoczynku.', 'magia', 'dnd', 'czary,sloty,zasoby', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (44, 'Proficjencja', 'Proficiency', 'Bonus dodawany do rzutów dla umiejętności, broni, narzędzi lub rzutów obronnych, w których postać jest biegła. Wzrasta wraz z poziomem postaci: +2 na 1-4 poziomie, aż do +6 na 17-20.', 'mechanika', 'dnd', 'proficiency,bonus,mechanika', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (45, 'Inspiracja', 'Inspiration', 'Żeton nagradzany przez MG za odgrywanie postaci zgodnie z jej tłem lub cechami. Można go wydać, aby uzyskać Przewagę na dowolny rzut ataku, testu zdolności lub rzutu obronnego.', 'mechanika', 'dnd', 'inspiration,roleplaying', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (46, 'Kości Życia', 'Hit Dice', 'Kości służące do odnawiania punktów życia podczas krótkiego odpoczynku. Każda klasa ma inną kość życia (np. Wojownik k10, Czarodziej k6). Łączna liczba równa się poziomowi postaci.', 'mechanika', 'dnd', 'HD,odpoczynek,HP', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (47, 'Wieloklasowość', 'Multiclassing', 'Wybór drugiej (lub kolejnej) klasy podczas zdobywania poziomu, zamiast rozwijania dotychczasowej. Pozwala łączyć zdolności różnych klas kosztem wolniejszego dostępu do zaawansowanych cech każdej z nich.', 'postac', 'dnd', 'multiclass,klasa,build', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (48, 'Zdolność Specjalna', 'Feat', 'Opcjonalna cecha postaci zdobywana zamiast podwyższenia atrybutu. Daje unikalne umiejętności lub premie (np. Alert — +5 do Inicjatywy, War Caster — utrzymywanie koncentracji z Przewagą).', 'postac', 'dnd', 'feat,cecha,build', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (49, 'BBEG', 'Big Bad Evil Guy', 'Główny antagonista kampanii lub przygody — osoba lub istota odpowiedzialna za zagrożenie, które bohaterowie muszą pokonać. Termin pochodzi ze slangu graczy i jest używany przez MG przy planowaniu fabuły.', 'narracja', 'uniwersalne', 'bbeg,antagonista,villain', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (50, 'MacGuffin', 'MacGuffin', 'Przedmiot lub cel, który napędza fabułę i motywuje bohaterów do działania, jednak sam w sobie nie ma większego znaczenia narracyjnego. Przykłady: zaginiony artefakt, skradziony kod, tajemnicza walizka.', 'narracja', 'uniwersalne', 'macguffin,fabuła,narracja', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (51, 'Improwizacja MG', 'GM Improv', 'Umiejętność tworzenia treści "na żywo" przez Mistrza Gry, gdy gracze schodzą z przygotowanej ścieżki. Klucz: zasada "tak, i..." — zaakceptuj akcję gracza i dodaj konsekwencję lub komplikację.', 'mg', 'uniwersalne', 'improv,mg,narracja', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (52, 'Obszar Efektu', 'Area of Effect', 'Czary lub zdolności działające na obszar, nie na pojedynczy cel. Typowe kształty: sfera (Fireball — 20 stóp), stożek (Breath Weapon), linia (Lightning Bolt), sześcian. Każda postać w obszarze może być dotknięta.', 'walka', 'dnd', 'AoE,czary,obszar,walka', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (53, 'Rzut na Atak', 'Attack Roll', 'Rzut k20 + modyfikator ataku (siła lub zręczność + bonus proficjencji) wykonywany przy próbie trafienia celu. Wynik musi równać się KP celu lub go przekraczać. Naturalne 20 to automatyczne trafienie i szansa na Krytyka.', 'walka', 'dnd', 'atak,k20,mechanika', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (54, 'Rzut na Obrażenia', 'Damage Roll', 'Rzut kością obrażeń broni lub czaru po trafieniu, wskazujący liczbę punktów życia zabranych celowi. Przy trafieniu krytycznym rzucasz dwa razy tyloma kośćmi i dodajesz wyniki.', 'walka', 'dnd', 'obrażenia,kości,mechanika', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (55, 'Tura', 'Turn', 'Pojedyncze działanie jednej postaci w ramach rundy walki. Podczas tury postać może wykonać: jedną Akcję, jeden Ruch (do wartości Prędkości), ewentualną Akcję Bonusową i jedną Reakcję.', 'walka', 'uniwersalne', 'tura,runda,walka', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (56, 'Runda', 'Round', 'Jeden pełny cykl walki, w którym każda uczestnicząca postać wykonuje swoją turę (zazwyczaj reprezentuje ok. 6 sekund w świecie gry). Po zakończeniu rundy inicjatywa się nie losuje — kolejność pozostaje.', 'walka', 'uniwersalne', 'runda,tura,walka', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (57, 'Teren Trudny', 'Difficult Terrain', 'Obszar spowalniający ruch — błoto, gruz, głęboka woda, gęste krzaki. Poruszanie się po terenie trudnym kosztuje dwa razy więcej Prędkości (każda stopa ruchu liczy się za dwie).', 'walka', 'dnd', 'teren,ruch,walka', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (58, 'Zasięg', 'Reach / Range', 'Odległość, na jaką postać lub broń może działać. Zasięg dotykowy (Reach) — dla broni wręcz, zwykle 5 stóp (10 dla broni drzewcowych). Zasięg dystansowy (Range) — dla broni/czarów dystansowych, dwa zakresy: normalny i długi (z Utrudnieniem).', 'walka', 'dnd', 'zasięg,broń,odległość', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (59, 'Ochrona', 'Cover', 'Osłona fizyczna zmniejszająca szansę bycia trafionym. Pół osłony: +2 do KP i rzutów obronnych na Zręczność. Trzy czwarte osłony: +5 do KP i rzutów obronnych. Pełna osłona: cel nie może być bezpośrednio atakowany.', 'walka', 'dnd', 'cover,ochrona,obrona', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (60, 'Karta Postaci', 'Character Sheet', 'Dokument (papierowy lub cyfrowy) zawierający wszystkie informacje o postaci gracza: atrybuty, umiejętności, HP, wyposażenie, zdolności i historię. Podstawowe narzędzie każdego gracza.', 'podstawy', 'uniwersalne', 'character-sheet,postać,formularz', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (61, 'Awans Postaci', 'Level Up', 'Zdobycie nowego poziomu postaci po uzbieraniu odpowiedniej liczby punktów doświadczenia (XP) lub po ukończeniu kamienia milowego fabuły. Awans przynosi nowe HP, zdolności klasy i co cztery poziomy wzrost atrybutów.', 'mechanika', 'dnd', 'level-up,poziom,rozwój', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (62, 'Ekran Mistrza Gry', 'GM Screen', 'Fizyczna lub cyfrowa bariera zasłaniająca notatki i rzuty MG przed graczami. Zwykle zawiera najczęściej używane tabele i zasady dla szybkiego odniesienia. Utrzymuje tajemnicę planowania i buduje napięcie.', 'mg', 'uniwersalne', 'ekran,mg,tabele', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (63, 'Klimat Sesji', 'Session Tone / Mood', 'Ogólny nastrój i atmosfera sesji — mroczna, komediowa, epicka, detektywistyczna. MG ustala go z graczami, zwłaszcza na Sesji Zerowej. Spójny klimat pomaga w odgrywaniu postaci i tworzeniu narracji.', 'narracja', 'uniwersalne', 'klimat,atmosfera,nastrój', '2026-05-14 12:03:17.918612');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (33, 'Spotkanie towarzyskie', 'Social Encounter', 'Scena negocjacji, przesłuchania albo dyplomacji, gdzie kluczowe są argumenty i relacje.', 'narracja', 'uniwersalne', 'social,interakcja', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (34, 'Encounter', 'Encounter', 'Pojedyncze wyzwanie dla drużyny: walka, przeszkoda terenowa, zagadka lub scena społeczna.', 'mechanika', 'uniwersalne', 'encounter,wyzwanie', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (37, 'Archetyp', 'Archetype', 'Wyraźny wzorzec roli postaci, np. obrońca, zwiadowca, mistyk lub wsparcie.', 'postacie', 'uniwersalne', 'archetyp,rola', '2026-05-14 12:03:17.511427');
INSERT INTO public.glossary_terms (id, term_pl, term_en, definition, category, system, tags, created_at) VALUES (38, 'Downtime', 'Downtime', 'Czas pomiędzy wyprawami przeznaczony na trening, handel, leczenie i rozwijanie wątków pobocznych.', 'narracja', 'uniwersalne', 'downtime,miedzy-sesjami', '2026-05-14 12:03:17.511427');
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (1, 'dnd', 'dice', 'Rzuty kośćmi', 'W D&D 5e większość testów opiera się o rzut k20.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (2, 'dnd', 'combat', 'Walka', 'Tura w walce zwykle dzieli się na ruch, akcję i czasem reakcję.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (3, 'dnd', 'attributes', 'Atrybuty', 'Atrybuty opisują fundament postaci: siłę, zręczność, wytrzymałość, intelekt, mądrość i charyzmę.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (4, 'dnd', 'rest', 'Odpoczynek', 'Odpoczynek porządkuje tempo kampanii.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (5, 'dnd', 'spells', 'Zaklęcia', 'Magia w D&D to zarządzanie zasobami i decyzjami taktycznymi.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (6, 'cthulhu', 'basics', 'Podstawy gry', 'Call of Cthulhu opiera się na grozie i bezsilności wobec rzeczy większych niż człowiek.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (7, 'cthulhu', 'basic-rules', 'Testy procentowe', 'Główny mechanizm to rzut k100 pod wartość umiejętności.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (8, 'cthulhu', 'sanity', 'Poczytalność', 'Sanity to zasób psychiczny postaci.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (9, 'cthulhu', 'combat', 'Starcia i przemoc', 'W CoC otwarta walka jest zwykle ostatecznością.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (10, 'cthulhu', 'fear', 'Strach i napięcie', 'Strach jest częścią rozgrywki, nie tylko opisem klimatu.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (12, 'wh4e', 'tests-and-sl', 'Testy i poziomy sukcesu', 'Poziomy sukcesu (SL) pokazują, jak bardzo akcja się udała lub nie.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (11, 'wh4e', 'core-loop', 'Warhammer 4ed: rdzeń gry', 'WFRP 4ed stawia na brudny, niebezpieczny świat i bohaterów, którzy często są bardziej sprytni niż potężni.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (13, 'wh4e', 'combat', 'Walka i zagrożenia', 'Starcia w WFRP bywają szybkie i bolesne.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (14, 'wh4e', 'career', 'Profesje i rozwój', 'Postać rozwija się przez profesje, które określają jej miejsce w świecie.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (16, 'pf2e', 'degrees', 'Stopnie powodzenia', 'W PF2e wiele testów ma cztery wyniki: krytyczny sukces, sukces, porażka, krytyczna porażka.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (18, 'pf2e', 'encounter-balance', 'Budowanie starć', 'Projektowanie spotkań opiera się o budżet zagrożenia i role przeciwników.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (15, 'pf2e', 'three-actions', 'Ekonomia trzech akcji', 'Każda tura daje trzy akcje i zwykle jedną reakcję.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (17, 'pf2e', 'conditions', 'Warunki i statusy', 'Warunki są precyzyjne i mają konkretne skutki mechaniczne.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (19, 'morkborg', 'tone', 'Klimat i założenia', 'Mork Borg to szybka, brutalna gra o końcu świata.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (20, 'morkborg', 'tests', 'Testy i tempo', 'Testy są proste, więc szybko przechodzisz do konsekwencji.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (21, 'morkborg', 'combat', 'Walka i przetrwanie', 'Starcia są śmiertelne, więc plan i pozycja znaczą więcej niż brawura.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (22, 'morkborg', 'loot-and-doom', 'Łup i zagłada', 'Świat pcha się ku katastrofie, a łupy kuszą ryzykiem.
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (23, 'swade', 'podstawy-systemu', 'Podstawy systemu', 'Savage Worlds to system RPG zaprojektowany pod hasłem "Fast! Furious! Fun!" — szybka, dynamiczna rozgrywka bez zbędnych przestojów.\n\nKluczowe cechy systemu:\n- Karty Inicjatywy: zamiast rzutów, inicjatywa jest losowana kartami z talii (asy i joker dają premie).\n- Karby (Bennies): żetony umożliwiające powtarzanie rzutów, absorbowanie obrażeń lub inne efekty. Standardowo gracz zaczyna z 3.\n- Postacie Dzikie (Wild Cards): bohaterowie graczy i ważne NPC — rzucają dodatkową "Dziką Kością" (k6) i wybierają lepszy wynik.\n- Zbiry (Extras): szeregowi przeciwnicy — bez Dzikiej Kości, padają od jednego trafienia z podniesionym poziomem sukcesu.', 'reference', 'Savage Worlds to system RPG zaprojektowany pod hasłem "Fast! Furious! Fun!" — szybka, dynamiczna rozgrywka bez zbędnych przestojów.  Kluczowe cechy systemu: - Karty Inicjatywy: zamiast rzutów, inicjatywa jest losowana kartami z talii (asy i', '{}', false, 100, 'Internal quick reference');
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (24, 'swade', 'rzuty-i-sukcesy', 'Rzuty i sukcesy', 'Rzuty w SWADE:\n- Rzucasz odpowiednią kością Atrybutu lub Umiejętności (k4, k6, k8, k10, k12).\n- Jako Dzika Karta rzucasz również k6 i wybierasz wyższy wynik.\n- Trudność standardowa: 4.\n- Sukces = wynik ≥ 4. Każde pełne 4 powyżej progu to Podniesienie (Raise), dające dodatkowy efekt.\n\nAsy (Acing):\n- Gdy na kości wypada jej maksimum (np. 6 na k6), rzucasz jeszcze raz i dodajesz do wyniku. Można wielokrotnie.\n\nModyfikatory:\n- Przeszkody, zranienie, warunki: modyfikatory od -1 do -4 lub więcej.\n- Atakowanie Zbiorów (Group Attack): -2 do ataku przy ostrzale kilku celów.', 'reference', 'Rzuty w SWADE: - Rzucasz odpowiednią kością Atrybutu lub Umiejętności (k4, k6, k8, k10, k12). - Jako Dzika Karta rzucasz również k6 i wybierasz wyższy wynik. - Trudność standardowa: 4. - Sukces = wynik ≥ 4. Każde pełne 4 powyżej progu to Po', '{}', false, 100, 'Internal quick reference');
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (25, 'swade', 'walka', 'Walka', 'Kolejność akcji wyznacza talia kart — każdy uczestnik walki dobiera kartę na początku rundy:\n- Wyższa karta = pierwszeństwo (As > K > D > W > 10 ... 2).\n- Kolor określa kolejność przy remisie (piki, kiery, kara, trefle).\n- Joker: możesz działać w dowolnym momencie rundy i dostajesz +2 do wszystkich rzutów.\n\nAkcje w turze:\n- Akcja (Action): atak, rzucanie czaru, aktywowanie zdolności.\n- Ruch (Movement): postać może poruszać się o SW w swoim Tempie (zwykle 6″).\n- Wolna Akcja: drobne czynności nie wymagające rzutu.\n\nAtaki i obrażenia:\n- Atak Wręcz / Broń palna: Walka vs Parry (cel) lub zwykły rzut vs trudność 4.\n- Obrażenia: rzut kością obrażeń broni + Siła (wręcz). Wynik vs Wytrzymałość (Toughness).', 'reference', 'Kolejność akcji wyznacza talia kart — każdy uczestnik walki dobiera kartę na początku rundy: - Wyższa karta = pierwszeństwo (As > K > D > W > 10 ... 2). - Kolor określa kolejność przy remisie (piki, kiery, kara, trefle). - Joker: możesz dzi', '{}', false, 100, 'Internal quick reference');
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (26, 'swade', 'obrenia-i-rankingi', 'Obrażenia i kondycja', 'Wytrzymałość (Toughness) = 2 + połowa Wigoru (Vigor) + ewentualna zbroja.\n\nProgi obrażeń:\n- Wynik obrażeń < Wytrzymałość: żadnego efektu.\n- ≥ Wytrzymałość: Ogłuszony (Shaken) — postać traci akcję, może tylko odzyskać przytomność lub się poruszać.\n- Podniesienie powyżej Wytrzymałości: Rana (Wound) — kara -1 do wszystkich rzutów (kumuluje się).\n\nDzika Karta może mieć max 3 Rany — przy 4. wypada z walki (nieprzytomna lub martwa, zależnie od narracji).\n\nOdnowa po walce:\n- Test Wigoru lub opieka medyczna (Healing) usuwa Rany.\n- Ogłuszenie odpada po udanym teście Ducha (Spirit) na początku tury.', 'reference', 'Wytrzymałość (Toughness) = 2 + połowa Wigoru (Vigor) + ewentualna zbroja.  Progi obrażeń: - Wynik obrażeń < Wytrzymałość: żadnego efektu. - ≥ Wytrzymałość: Ogłuszony (Shaken) — postać traci akcję, może tylko odzyskać przytomność lub się por', '{}', false, 100, 'Internal quick reference');
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (27, 'swade', 'zdolnosci-i-atuty', 'Zdolności i Atuty', 'Atrybuty (5 sztuk): Agility, Smarts, Spirit, Strength, Vigor — na skali k4 → k12.\nUmiejętności: powiązane z atrybutami; rzucasz kością Umiejętności (lub k4 jeśli jej nie masz).\n\nAtuty (Edges):\n- Zdobywane na starcie i przy awansach.\n- Wymagają zazwyczaj określonego ranku (Nowicjusz, Doświadczony, Weteran, Bohater, Legenda).\n- Przykłady: Tough as Nails (+1 Wytrzymałość), Frenzy (dwa ataki wręcz), Marksman (+2 do ataków dystansowych po braku ruchu).\n\nAwanse (Advances):\n- Co 5 XP postać dostaje Awans.\n- Awans = podnieś Umiejętność, zdobądź Atut lub zwiększ Atrybut (raz na 2 awanse).', 'reference', 'Atrybuty (5 sztuk): Agility, Smarts, Spirit, Strength, Vigor — na skali k4 → k12. Umiejętności: powiązane z atrybutami; rzucasz kością Umiejętności (lub k4 jeśli jej nie masz).  Atuty (Edges): - Zdobywane na starcie i przy awansach. - Wymag', '{}', false, 100, 'Internal quick reference');
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (28, 'swade', 'magiczne-systemy', 'Magia i moce', 'W SWADE nie ma jednego systemu magii — zamiast tego istnieją "Arkaniczne Zaplecza" (Arcane Backgrounds):\n- Magia (Magic): tradycyjny czarownik.\n- Cuda (Miracles): kapłan lub wyznawca.\n- Psychika (Psionics): moce mentalne.\n- Super Moce (Super Powers): bohaterowie komiksowi.\n\nMoce kosztują Punkty Mocy (Power Points, PP). Rzucasz Arcaną (Arcane skill) vs trudność 4.\n- Sukces: moc działa normalnie.\n- Raise: wzmocniony efekt.\n- Porażka: PP stracone, moc nie działa.\n- 1 na kości Arcany: Backfire — efekt uboczny.\n\nPunkty Mocy odnawiają się w tempie 1 PP/godz. lub szybciej dzięki specjalnym zdolnościom.', 'magic', 'W SWADE nie ma jednego systemu magii — zamiast tego istnieją "Arkaniczne Zaplecza" (Arcane Backgrounds): - Magia (Magic): tradycyjny czarownik. - Cuda (Miracles): kapłan lub wyznawca. - Psychika (Psionics): moce mentalne. - Super Moce (Supe', '{}', false, 100, 'Internal quick reference');
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (29, 'alien', 'podstawy-systemu', 'Podstawy systemu', 'Alien RPG to gra oparta na silniku Year Zero Engine, osadzona w oficjalnym kanonie filmów Alien. Klimat: horror survivalowy, kosmiczny terror, paranoja i człowiek jako najsłabsze ogniwo.\n\nCentrum mechaniki: rzuty pulą kości k6.\n- Rzucasz liczbą k6 równą wartości Atrybutu + Umiejętności.\n- Cel: uzyskać co najmniej jedną szóstkę.\n- Każda dodatkowa szóstka to Atut (Push) — dodatkowy efekt.\n\nDwa tryby gry:\n- Tryb Korytarza (Cinematic): jednorazowe, intensywne sesje z gotowymi agendami i ukrytymi celami dla graczy. Wysoka śmiertelność.\n- Tryb Kampanii (Campaign): standardowe, dłuższe sesje, nastawione na przetrwanie i eksplorację.', 'reference', 'Alien RPG to gra oparta na silniku Year Zero Engine, osadzona w oficjalnym kanonie filmów Alien. Klimat: horror survivalowy, kosmiczny terror, paranoja i człowiek jako najsłabsze ogniwo.  Centrum mechaniki: rzuty pulą kości k6. - Rzucasz li', '{}', false, 100, 'Internal quick reference');
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (30, 'alien', 'rzuty-i-pula-kosci', 'Rzuty i pula kości', 'Pula kości = Atrybut + Umiejętność (+ ewentualne modyfikatory).\n- Minimalna pula: 1k6.\n- Maksymalna pula: zalecane 10k6.\n\nWynik:\n- ≥1 szóstka: sukces.\n- Każda dodatkowa szóstka: Atut — możesz wybrać efekty z listy dla danej umiejętności.\n- 0 szóstek: porażka.\n\nPush (Popychanie):\n- Możesz powtórzyć nieudany rzut raz.\n- Rzucasz ponownie wszystkimi kośćmi BEZ szóstek z poprzedniego rzutu.\n- Każda jedynka (1) w łącznym wyniku Push-a zwiększa Poziom Stresu o 1.\n\nKości Paniki:\nGdy Stres jest wysoki, rzucasz Kością Paniki (k6) — wynik ≤ aktualnemu Stresowi wywołuje Panikę, której efekt losowany jest z tabeli.', 'reference', 'Pula kości = Atrybut + Umiejętność (+ ewentualne modyfikatory). - Minimalna pula: 1k6. - Maksymalna pula: zalecane 10k6.  Wynik: - ≥1 szóstka: sukces. - Każda dodatkowa szóstka: Atut — możesz wybrać efekty z listy dla danej umiejętności. - ', '{}', false, 100, 'Internal quick reference');
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (31, 'alien', 'stres-i-panika', 'Stres i Panika', 'Stres (Stress Level) to kluczowy zasób survivalowy:\n- Zaczyna się od 0.\n- Wzrasta przy: Push-owaniu rzutów, traumatycznych wydarzeniach, śmierci towarzyszy, obecności Obcego.\n- Spada przy: odpoczynku, medytacji, pomyślnym zakończeniu niebezpiecznych sytuacji.\n\nTest Paniki:\n- Wykonywany gdy Stres > 0 i dochodzi do Pushowania lub specjalnych triggerów.\n- Rzucasz k6 — jeśli wynik ≤ Poziom Stresu → Panika.\n\nTabela Paniki (k6 + Stres):\n2-6: Drżenie — kara -1 do następnego rzutu.\n7-8: Strach — upuszczasz ekwipunek lub krzyczysz.\n9-10: Ucieczka — musisz natychmiast uciec od źródła strachu.\n11-12: Katatoniczny bezruch — nie możesz nic zrobić przez jedną rundę.\n13+: Frenezja — niekontrolowany atak na najbliższą postać.\n\nPanika jest zaraźliwa — inni gracze w pobliżu testują Panikę przy wyniku 10+.', 'reference', 'Stres (Stress Level) to kluczowy zasób survivalowy: - Zaczyna się od 0. - Wzrasta przy: Push-owaniu rzutów, traumatycznych wydarzeniach, śmierci towarzyszy, obecności Obcego. - Spada przy: odpoczynku, medytacji, pomyślnym zakończeniu niebez', '{}', false, 100, 'Internal quick reference');
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (32, 'alien', 'walka-i-przetrwanie', 'Walka i przetrwanie', 'Inicjatywa:\n- Rzucasz Sprawnością (Agility) — wyższy wynik działa pierwszy.\n- W przypadku remisu: atakujący ma pierwszeństwo.\n\nAkcje w turze:\n- Szybka Akcja: strzał, ruch o 10m, wyjęcie broni.\n- Powolna Akcja: atak wręcz, pierwsza pomoc, interakcja ze sprzętem.\n- Postać może wykonać jedną Szybką i jedną Powolną akcję na turę.\n\nObrażenia i zdrowie:\n- Zdrowie = Wytrzymałość (Strength). Przy 0 HP → Złamany (Broken), wypadasz z walki.\n- Krytyczne obrażenia: każdy atak, który zabiera ostatnie HP, może spowodować losowy efekt krytyczny (k6 + tabela).\n- Obrażenia broni: pistolet 1k6, karabin 2k6, strzelba 3k6 (blisko).\n\nEkwipunek survivalowy:\n- Kombinezon EVA: ochrona przed próżnią i utratą ciśnienia.\n- Miotacz ognia: 3k6 obrażeń, ale uwaga na płomienie w ciasnych korytarzach.', 'reference', 'Inicjatywa: - Rzucasz Sprawnością (Agility) — wyższy wynik działa pierwszy. - W przypadku remisu: atakujący ma pierwszeństwo.  Akcje w turze: - Szybka Akcja: strzał, ruch o 10m, wyjęcie broni. - Powolna Akcja: atak wręcz, pierwsza pomoc, in', '{}', false, 100, 'Internal quick reference');
INSERT INTO public.rules_pages (id, system_code, slug, title, content, category, summary, tags, quick_ref, sort_order, source_label) VALUES (33, 'alien', 'obcy-i-zagroenia', 'Ksenomofrfy i zagrożenia', 'Ksenomorf (Xenomorph):\n- Nie można ich zranić standardową bronią bez Kości Paniki.\n- Każda konfrontacja twarzą w twarz: test Paniki lub Stresu +2.\n- Kwas: gdy Obcy ginie, kwas tryska w zasięgu 1m — obrażenia 1k6 za turę kontaktu.\n- Wykrywanie: ruch na peryferiach wzroku, stukanie w ściany, shadow play — sygnały ostrzegawcze dla MG.\n\nFace Hugger:\n- Atak: Sprawność vs Sprawność. Sukces = przytwierdzenie do twarzy.\n- Niemożliwy do usunięcia bez specjalnego sprzętu lub operacji.\n- Po czasie: implantacja embrionu.\n\nZasady atmosfery i środowiska:\n- Próżnia: bez kombinezonu → 1k6 obrażeń/runda, od 3. rundy → krytyczne.\n- Temperatura: skrajny ziąb lub żar → +1 Stres/scena bez ochrony.\n- Ciemność: -2 do rzutów na percepcję i walkę w ciemnościach.', 'reference', 'Ksenomorf (Xenomorph): - Nie można ich zranić standardową bronią bez Kości Paniki. - Każda konfrontacja twarzą w twarz: test Paniki lub Stresu +2. - Kwas: gdy Obcy ginie, kwas tryska w zasięgu 1m — obrażenia 1k6 za turę kontaktu. - Wykrywan', '{}', false, 100, 'Internal quick reference');
